macro.command:
if (args[0]?.macroPass !== "postDamageRoll" || workflow.aborted) return;
const actor = workflow.actor;
if (workflow.item?.type !== "spell" || !actor) return;
if (workflow.workflowOptions?.isOverTime || workflow.activity?.isOverTimeFlag) return;
const sorcerer = actor.items.find(item => item.type === "class" && item.system.identifier === "sorcerer");
if (Number(sorcerer?.system.levels ?? 0) < 6) return;
if (!actor.items.some(item => item.system.identifier === "elemental-affinity"
  || item._stats?.compendiumSource?.endsWith(".U5Qd4JBsnqhBC4Vv"))) return;

const selected = actor.getRollData().scale?.["draconic-ancestry"]?.["damage-type"];
const damageType = typeof selected === "string" ? selected : String(selected?.value ?? selected ?? "");
if (!["acid", "cold", "fire", "lightning", "poison"].includes(damageType)) {
  return ui.notifications.warn("元素亲和：请先在龙族血脉升级中选择巨龙先祖。");
}
const rolls = [...(workflow.damageRolls ?? [])];
const index = rolls.findIndex(roll => roll.options?.type === damageType);
if (index < 0 || workflow._classpackElementalAffinity) return;
workflow._classpackElementalAffinity = true;

// 合并已评估的伤害骰与固定加值，保留原骰结果、伤害类型和重击结果。
const charisma = Number(actor.system.abilities.cha.mod);
if (Number.isFinite(charisma) && charisma > 0) {
  try {
    const bonus = await new Roll(`${charisma}[元素亲和]`).evaluate();
    rolls[index] = MidiQOL.addRollTo(rolls[index], bonus);
    await workflow.setDamageRolls(rolls);
  } catch (error) {
    delete workflow._classpackElementalAffinity;
    throw error;
  }
}

const classpack = globalThis.dnd5eClasspack;
const points = actor.items.find(item => item.system.identifier === "sorcery-points"
  || item._stats?.compendiumSource?.endsWith(".Q3AW3csi2dBTMvPm"));
if (!points || !classpack?.resources || classpack.resources.remaining(points) < 1) return;
const label = game.i18n.localize(CONFIG.DND5E.damageTypes[damageType].label);
const answer = await classpack.dialogUtils.buttonDialog(
  "元素亲和", `是否花费 1 术法点，获得持续 1 小时的${label}伤害抗性？`,
  [["获得抗性", "gain"], ["不使用", "skip"]],
  { userId: classpack.firstOwner(actor, true) }
);
if (answer !== "gain") return;

let receipt;
try {
  receipt = await classpack.resources.consume([{ itemUuid: points.uuid, amount: 1 }], {
    id: `${workflow.uuid ?? workflow.id ?? foundry.utils.randomID()}:elemental-affinity-resistance`
  });
  const effects = await actor.createEmbeddedDocuments("ActiveEffect", [{
    name: `元素亲和：${label}抗性`, img: "icons/magic/symbols/elements-air-earth-fire-water.webp",
    type: "base", transfer: false,
    duration: { value: 1, units: "hours", expiry: null },
    system: {
      magical: true, origin: { item: workflow.item.uuid },
      changes: [{ _id: foundry.utils.randomID(), key: "system.traits.dr.value", value: damageType,
        type: "add", phase: "initial", priority: 20, conditions: "{}", replacement: "" }]
    },
    flags: { dae: { expiryMode: "delete" } }
  }]);
  if (!effects?.length) throw new Error("未能创建抗性效应");
} catch (error) {
  // 创建失败时，仅在资源未发生其他变化的情况下退回本次扣除。
  for (const entry of [...(receipt?.entries ?? [])].reverse()) {
    const item = await fromUuid(entry.itemUuid);
    if (Number(item?.system.uses.spent) === entry.after) {
      await item.update({ "system.uses.spent": entry.before });
    }
  }
  console.error("元素亲和：抗性处理失败", error);
  ui.notifications.error("元素亲和：抗性处理失败，请检查控制台及术法点余额。");
}
